<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { RouterLink } from "vue-router";
import { ArrowRight, BookOpen, CheckCircle2, ChevronRight, CirclePlay, Clock3, FileVideo, GraduationCap, Lightbulb, RefreshCw, Sparkles, Target, Upload, Workflow } from "lucide-vue-next";
import { api } from "@/api/client";
import type { Sop } from "@/api/types";
import type { PracticeCourse, PracticeSession } from "@/api/practice";
import LearningCourseCard from "@/components/LearningCourseCard.vue";
import { displayProcessName } from "@/services/displayNames";
import { useAuthStore } from "@/stores/auth";
const auth = useAuthStore();
const courses = ref<PracticeCourse[]>([]);
const history = ref<PracticeSession[]>([]);
const sops = ref<Sop[]>([]);
const loading = ref(true);
const error = ref("");
const canTeach = computed(() => ["admin", "instructor"].includes(auth.user?.role || ""));
const readyCourses = computed(() => courses.value.filter(c => !c.issues.length));
const ongoing = computed(() => history.value.find(h => ["active", "paused"].includes(h.status)));
const finished = computed(() => history.value.filter(h => h.status === "finished").length);
const draftCount = computed(() => sops.value.filter(s => s.status === "draft").length);
const recent = computed(() => history.value.slice(0, 4));
const progressOf = (item: PracticeSession) => item.steps.length ? Math.round((item.state.completed.length + item.state.skipped.length) / item.steps.length * 100) : 0;
function courseProgress(id: string) { const item = history.value.find(h => h.sop_id === id); return item ? progressOf(item) : null; }
function sessionTitle(item: PracticeSession) { const course = courses.value.find(c => c.sop_id === item.sop_id); return course ? (course.course_meta?.title || displayProcessName(course.process_key)) : (item.course?.course_meta?.title || `${item.steps[0]?.name || '技能实训'} · ${item.steps.length} 步`); }
function dateLabel(value: string) { return new Date(value).toLocaleDateString("zh-CN", { month: "2-digit", day: "2-digit" }); }
const statusLabel = { active: "练习中", paused: "已暂停", finished: "已完成", stopped: "已结束" };
async function loadDashboard() {
  if (loading.value && courses.value.length) return;
  loading.value = true; error.value = "";
  try {
    const [catalog, sessions, versions] = await Promise.all([
      api.get<{ courses: PracticeCourse[]; provider_configured: boolean }>("/practice-sessions/courses"),
      api.get<PracticeSession[]>("/practice-sessions"),
      canTeach.value ? api.get<Sop[]>("/sops") : Promise.resolve([] as Sop[]),
    ]);
    courses.value = catalog.courses; history.value = sessions; sops.value = versions;
  } catch (e) { error.value = e instanceof Error ? e.message : "学习记录加载失败"; }
  finally { loading.value = false; }
}
onMounted(loadDashboard);
</script>
<template>
  <section class="learning-home" :aria-busy="loading">
    <header class="home-head"><div><div class="eyebrow">YOUR LEARNING SPACE</div><h1>你好，{{ auth.user?.display_name || auth.user?.username }} <span class="greeting-dot">✦</span></h1><p>从一段示范开始，把知识变成动手能力。</p></div><RouterLink v-if="canTeach" to="/knowledge" class="secondary-button"><Upload :size="15" />导入教学视频</RouterLink></header>
    <div v-if="error" class="load-error" role="alert"><span>{{ error }}</span><button @click="loadDashboard"><RefreshCw :size="15" />重新加载</button></div>
    <section class="learning-hero">
      <div class="hero-copy"><span class="hero-badge"><Sparkles :size="12" />你的 AI 技能陪练</span><h2>看得懂，更要<span>做得到。</span></h2><p>标准示范拆成清晰步骤，练习过程获得及时反馈。<br />每一步，都离真正掌握更近一点。</p><div class="hero-actions"><RouterLink :to="ongoing ? `/practice/${ongoing.id}` : '/practice'" class="primary-button"><CirclePlay :size="17" />{{ ongoing ? '继续上次练习' : '进入实训课堂' }}<ArrowRight :size="15" /></RouterLink><RouterLink :to="canTeach ? '/sops' : '/assessment'" class="hero-link">{{ canTeach ? '创建我的课程' : '查看学习评估' }}<ChevronRight :size="14" /></RouterLink></div></div>
      <div class="hero-visual" aria-hidden="true"><div class="visual-orbit orbit-one"></div><div class="visual-orbit orbit-two"></div><div class="lesson-window"><div class="window-head"><span></span><span></span><span></span><i>AI LEARNING</i></div><div class="window-video"><CirclePlay :size="43" :stroke-width="1.25" /><div class="video-line"></div></div><div class="window-check"><span><CheckCircle2 :size="16" />标准示范</span><span><CheckCircle2 :size="16" />逐步掌握</span></div></div><div class="floating-note"><span><Sparkles :size="18" /></span><div><strong>看 · 练 · 评</strong><small>把进步看得见</small></div></div><div class="floating-cap"><GraduationCap :size="27" /></div></div>
    </section>
    <div class="stats-grid"><article class="stat-card"><span class="stat-icon violet"><BookOpen :size="20" /></span><div><span>可学习课程</span><strong>{{ loading || error ? '—' : readyCourses.length }}<small>门</small></strong></div></article><article class="stat-card"><span class="stat-icon blue"><Target :size="20" /></span><div><span>近期练习</span><strong>{{ loading || error ? '—' : history.length }}<small>次</small></strong></div></article><article class="stat-card"><span class="stat-icon mint"><CheckCircle2 :size="20" /></span><div><span>已完成练习</span><strong>{{ loading || error ? '—' : finished }}<small>次</small></strong></div></article><article class="stat-card"><span class="stat-icon peach"><component :is="canTeach ? FileVideo : Lightbulb" :size="20" /></span><div><span>{{ canTeach ? '备课中课程' : '近期纠错反馈' }}</span><strong>{{ loading || error ? '—' : canTeach ? draftCount : history.reduce((sum, h) => sum + h.state.error_count, 0) }}<small>{{ canTeach ? '份' : '次' }}</small></strong></div></article></div>
    <div class="home-grid"><section class="course-section"><div class="section-head"><div><h2>开始你的下一次学习</h2><p>示范、练习与反馈，连接在同一门课程里。</p></div><RouterLink to="/practice">全部课程<ArrowRight :size="14" /></RouterLink></div><div v-if="loading" class="course-grid"><div v-for="n in 3" :key="n" class="course-skeleton"></div></div><div v-else-if="courses.length" class="course-grid" :class="{ 'course-grid--small': courses.length < 3 }"><LearningCourseCard v-for="course in [...readyCourses, ...courses.filter(c => c.issues.length)].slice(0,3)" :key="course.sop_id" :course="{ title: course.course_meta?.title || displayProcessName(course.process_key), lessons: course.step_count, version: course.version, ready: !course.issues.length, progress: courseProgress(course.sop_id) }" :to="{ path: '/practice', query: { course: course.sop_id } }" :action-label="courseProgress(course.sop_id) !== null ? '继续学习' : '查看课程'" /><RouterLink v-if="canTeach && courses.length === 1" to="/knowledge" class="create-course-tile"><span><Upload :size="25" /></span><h3>创建下一门技能课程</h3><p>把你的标准示范整理成可以逐步练习的课堂。</p><strong>导入教学视频<ArrowRight :size="14" /></strong></RouterLink></div><div v-else class="course-empty"><span><BookOpen :size="30" /></span><h3>第一门技能课程，从这里开始</h3><p>{{ canTeach ? '上传标准教学视频，校对步骤和完成条件，发布后即可带领学员练习。' : '教师发布课程后，你就可以在这里开启实训。' }}</p><RouterLink v-if="canTeach" to="/knowledge" class="primary-button"><Upload :size="15" />上传教学视频</RouterLink><button v-else class="secondary-button" @click="loadDashboard"><RefreshCw :size="15" />刷新课程</button></div></section>
    <aside class="learning-side"><section class="recent-panel"><div class="section-head"><h2>最近的学习</h2><Clock3 :size="17" /></div><div v-if="!recent.length" class="recent-empty"><span class="empty-line"></span><p>还没有练习记录</p><small>完成第一次实训，让进步留下足迹。</small></div><RouterLink v-for="item in recent" :key="item.id" :to="`/practice/${item.id}`" class="recent-item"><span class="recent-dot" :class="item.status"><CheckCircle2 v-if="item.status === 'finished'" :size="15" /><CirclePlay v-else :size="15" /></span><div><strong>{{ sessionTitle(item) }}</strong><small>{{ dateLabel(item.created_at) }} · {{ statusLabel[item.status] }}</small><div class="mini-progress"><span :style="{ width: `${progressOf(item)}%` }"></span></div></div><span class="recent-percent">{{ progressOf(item) }}%</span></RouterLink><small v-if="history.length" class="history-note">基于最近 {{ history.length }} 次个人练习</small></section><section class="learning-tip"><Lightbulb :size="21" /><h3>给下一次练习的小建议</h3><p>先看一遍完整示范。练习时让目标物完整入镜，操作结束后移开手，让完成状态清楚可见。</p><RouterLink to="/practice">去试一试<ArrowRight :size="14" /></RouterLink></section></aside></div>
    <section class="learning-journey"><div class="journey-label"><Workflow :size="19" /><div><h2>一条完整的技能学习路径</h2><p>从标准视频，到独立完成。</p></div></div><RouterLink v-for="(item,index) in canTeach ? [{to:'/knowledge',label:'导入教学视频',note:'保留标准操作与讲解'},{to:'/sops',label:'编排学习步骤',note:'校对示范与完成条件'},{to:'/practice',label:'开启 AI 陪练',note:'边操作，边获得反馈'}] : [{to:'/practice',label:'选择实训课程',note:'找到本次练习目标'},{to:'/practice',label:'观看步骤示范',note:'看清操作与完成状态'},{to:'/assessment',label:'复盘学习结果',note:'对照反馈巩固技能'}]" :key="item.to + index" :to="item.to" class="journey-step"><span>{{ String(index+1).padStart(2,'0') }}</span><div><strong>{{ item.label }}</strong><small>{{ item.note }}</small></div><ChevronRight :size="15" /></RouterLink></section>
  </section>
</template>
